SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0440000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 44, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "44", "printedPageNumber": 44, "pdfPageNumber": 427, "sequenceIndex": 34, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0440000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "are those whom trade and business did not distract from remembrance of Allah?'' Yet another group will rise up and enter Paradise.\" In another hadith, the same account is given, with the addition that in the beginning the angel will say, \"All those gathered here will see today who are the honoured people\", and with the modification that the angel at the time of third announcement will say, ''Where are those whom their engagement in trade and business did not distract from salaat and remembrance of Allah?''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Sheik Nasr Samarqandi (Rahmatullah alaih), after quoting this Hadith writes, \"When all the three groups will have entered Paradise without reckoning, a monster with a long neck, shining eyes and most eloquent tongue will rise up from Hell and say, ''I have been deputed on all who are proud and ill-tempered.'' It will then pick up all such persons from the crowd, as a fowl picks up grain and then it will fling them into the Hell. It will rise up again saying, ''This time I have been deputed on all who maligned Allah and His Apostle (Sallallaho alaihe wasallam).'' It will then pick up all such persons and throw them into the Hell; it will appear for the third time and will, in a similar manner, take away all those who made images and pictures. The reckoning will then commence after these three groups have been eliminated.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said that during the early times people could see Satan. A person approached him saying how could he be like him. Satan told him that he had never received such a request before and asked him what had prompted him to ask for it. The person told him that he wished it from his heart. Satan told him to neglect his salaat and to swear very frequently, not caring whether he was doing it truthfully. The person told Satan that he would swear by Allah never to give up salaat and swear falsely. Satan told him that never before had he been tricked by a human being to seek his advice. He was determined never to do so in future.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ubayy (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Give glad tidings to the Muslims that they shall be honoured and exalted, and their religion shall prevail, but there is no portion in the Hereafter for those who exploit Islam for worldly gains.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported to have said, \"I saw Allah in His best form. He said to me, ''O Muhammad! what are the Highest Chiefs (Angels) arguing about?'' I said, ''I have no knowledge about that.'' Allah", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}]}'::jsonb);